syntax:
class A { public: virtual void f() {} };
class B : virtual public A {};
class C : virtual public A {};
class D : public B, public C {};

code_example:
#include <iostream>
class A { public: virtual void f() { std::cout << "A::f()\n"; } };
class B : virtual public A { public: void f() override { std::cout << "B::f()\n"; } };
class C : virtual public A { public: void f() override { std::cout << "C::f()\n"; } };
class D : public B, public C { };
int main() {
  D d;
  d.f(); // Which f() will be called?  The behavior is compiler-dependent if f() wasn't declared virtual in A.
  return 0;
}
